SELECT product_id, store_id, CASE WHEN revenue >= 3100 THEN 'high' WHEN revenue >= 1000 THEN 'mid' ELSE 'low' END AS revenue_bucket, SUM(units) AS total_units, MIN(revenue) AS min_revenue, ROUND(AVG(revenue), 2) AS avg_revenue FROM store_sales GROUP BY product_id, store_id, CASE WHEN revenue >= 3100 THEN 'high' WHEN revenue >= 1000 THEN 'mid' ELSE 'low' END HAVING MIN(revenue) >= 1900 ORDER BY total_units, product_id, store_id, revenue_bucket LIMIT 5
